fn parseI16(s: []const u8) !i16 {
    var neg: bool = false;
    var i: usize = 0;
    if (i < s.len and s[i] == '-') {
        neg = true;
        i += 1;
    } else if (i < s.len and s[i] == '+') {
        i += 1;
    }

    var acc: i16 = 0;
    var started: bool = false;
    while (i < s.len) {
        const c = s[i];
        if (c < '0' or c > '9') break;
        started = true;
        acc = acc * 10 - @as(i16, c - '0'); // accumulate negative to avoid overflow on INT_MIN
        i += 1;
    }

    if (!started) return error.InvalidIntegerLiteral;

    if (neg) return acc;
    return -acc;
}
